
# apl-source:1
# مثال 695 — شريحة كاتمول-روم
# apl-source:2
# Catmull-Rom spline
# apl-source:3
# Demonstrates: استيفاء هرمايت، توتر، مقاطع
# apl-source:4
#
# apl-source:5
# Run:  python apl.py examples/695-catmull-rom.apl
# apl-source:6

# apl-source:7
# Assertion style:
# apl-source:8
#   دالة تأكد_يساوي(فعلي, متوقع, اسم):
# apl-source:9
#     لو فعلي != متوقع:
# apl-source:10
#       اطبع "فشل:", اسم
# apl-source:11
#       اطبع "  متوقع:", متوقع
# apl-source:12
#       اطبع "  فعلي:", فعلي
# apl-source:13
#       قياسي_نظام_اخرج(1)
# apl-source:14
#     اطبع "ناجح:", اسم
# apl-source:15

# apl-source:16
def تأكد_يساوي(فعلي, متوقع, اسم):
  # apl-source:17
  if فعلي != متوقع:
    # apl-source:18
    print("فشل:", اسم)
    # apl-source:19
    print("  متوقع:", متوقع)
    # apl-source:20
    print("  فعلي:", فعلي)
    # apl-source:21
    قياسي_نظام_اخرج(1)
  # apl-source:22
  print("ناجح:", اسم)
# apl-source:23

# apl-source:24
# شريحة كاتمول-روم: منحنى يمر بكل نقاط التحكم
# apl-source:25
# Demonstrates: استيفاء هرمايت, توتر نصف, مقطع بين نقطتين
# apl-source:26
# على عكس بيزييه، المنحنى يمر فعلا بالنقاط
# apl-source:27

# apl-source:28
def كاتمول(ن0, ن1, ن2, ن3, ت):
  # apl-source:29
  ت2 = ت * ت
  # apl-source:30
  ت3 = ت2 * ت
  # apl-source:31
  س = 0.5 * ((2 * ن1[0]) + (ن2[0] - ن0[0]) * ت + (2 * ن0[0] - 5 * ن1[0] + 4 * ن2[0] - ن3[0]) * ت2 + (3 * ن1[0] - ن0[0] - 3 * ن2[0] + ن3[0]) * ت3)
  # apl-source:32
  ع = 0.5 * ((2 * ن1[1]) + (ن2[1] - ن0[1]) * ت + (2 * ن0[1] - 5 * ن1[1] + 4 * ن2[1] - ن3[1]) * ت2 + (3 * ن1[1] - ن0[1] - 3 * ن2[1] + ن3[1]) * ت3)
  # apl-source:33
  return [س, ع]
# apl-source:34

# apl-source:35
نقاط = [[0, 0], [1, 1], [2, 1], [3, 0]]
# apl-source:36
تأكد_يساوي(كاتمول(نقاط[0], نقاط[1], نقاط[2], نقاط[3], 0.0), [1.0, 1.0], "يبدأ من ن1")
# apl-source:37
تأكد_يساوي(كاتمول(نقاط[0], نقاط[1], نقاط[2], نقاط[3], 1.0), [2.0, 1.0], "ينتهي عند ن2")
# apl-source:38
منتصف = كاتمول(نقاط[0], نقاط[1], نقاط[2], نقاط[3], 0.5)
# apl-source:39
تأكد_يساوي(منتصف, [1.5, 1.125], "المنتصف أعلى من الوتر")
# apl-source:40
مسار = []
# apl-source:41
for ي in range(5):
  # apl-source:42
  مسار.append(كاتمول(نقاط[0], نقاط[1], نقاط[2], نقاط[3], ي / 4.0))
# apl-source:43
تأكد_يساوي(مسار[4], [2.0, 1.0], "آخر عينة عند ن2")
# apl-source:44
تأكد_يساوي(مسار[0][1] < مسار[2][1], True, "المنحنى ينتفخ للأعلى")
# apl-source:45
print("المنتصف:", منتصف)
# apl-source:46
